query:
SELECT p.id, p.enterpriseName, p.status, p.industry, p.website FROM projects p WHERE p.enterpriseName='海豚知道';
SELECT gs.totalScore, gs.visibilityLevel, gs.aiVisibilityScore, gs.aiRecommendationScore, gs.competitorWinScore, gs.cognitionAccuracyScore, gs.contentAssetScore FROM geo_scores gs JOIN projects p ON gs.projectId=p.id WHERE p.enterpriseName='海豚知道' ORDER BY gs.id DESC LIMIT 1;
SELECT cp.competitorName, cp.positioning, LEFT(cp.comparisonNotes, 120) AS comparison_excerpt FROM competitor_profiles cp JOIN projects p ON cp.projectId=p.id WHERE p.enterpriseName='海豚知道' ORDER BY cp.id;
SELECT COUNT(*) AS published_records, SUM(CASE WHEN needRetest=1 THEN 1 ELSE 0 END) AS need_retest_records FROM geo_publish_records gpr JOIN projects p ON gpr.projectId=p.id WHERE p.enterpriseName='海豚知道';
SELECT COUNT(*) AS articles_with_generation_basis, SUM(CASE WHEN LENGTH(COALESCE(factTraceability,''))=0 THEN 1 ELSE 0 END) AS articles_empty_fact_traceability, SUM(CASE WHEN LENGTH(COALESCE(consistencyCheck,''))=0 THEN 1 ELSE 0 END) AS articles_empty_consistency_check FROM geo_articles ga JOIN projects p ON ga.projectId=p.id WHERE p.enterpriseName='海豚知道';

